export function eventSchema(event: {
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  location: { streetAddress: string; addressLocality: string; addressCountry: string };
  url: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Event',
    name: event.name,
    description: event.description,
    startDate: event.startDate,
    endDate: event.endDate,
    eventStatus: 'EventScheduled',
    eventAttendanceMode: 'OfflineEventAttendanceMode',
    location: {
      '@type': 'Place',
      address: {
        '@type': 'PostalAddress',
        streetAddress: event.location.streetAddress,
        addressLocality: event.location.addressLocality,
        addressCountry: event.location.addressCountry,
      },
    },
    organizer: {
      '@type': 'Organization',
      name: 'ELC',
      url: SITE_URL,
    },
    url: event.url,
  };
}

export function offerSchema(offer: {
  name: string;
  price: number;
  priceCurrency: string;
  validFrom: string;
  validThrough?: string;
  description?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Offer',
    name: offer.name,
    description: offer.description || '',
    price: offer.price,
    priceCurrency: offer.priceCurrency,
    validFrom: offer.validFrom,
    ...(offer.validThrough && { validThrough: offer.validThrough }),
    availability: 'InStock',
    offerCount: 999,
  };
}

export function videoSchema(video: {
  name: string;
  description: string;
  thumbnailUrl: string;
  uploadDate: string;
  duration: string;
  url?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'VideoObject',
    name: video.name,
    description: video.description,
    thumbnailUrl: video.thumbnailUrl,
    uploadDate: video.uploadDate,
    duration: video.duration,
    ...(video.url && { contentUrl: video.url }),
  };
}

export function reviewSchema(review: {
  text: string;
  author: string;
  rating: number;
  datePublished?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Review',
    reviewRating: {
      '@type': 'Rating',
      ratingValue: Math.round(review.rating),
      bestRating: '5',
      worstRating: '1',
    },
    author: {
      '@type': 'Person',
      name: review.author,
    },
    reviewBody: review.text,
    ...(review.datePublished && { datePublished: review.datePublished }),
  };
}

// HTML-escape utility for JSON-LD script tags (call on stringified JSON in Layout)
export function escapeJsonLd(jsonString: string): string {
  return jsonString
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026');
}

export function aggregateReviewSchema(reviews: {
  ratingValue: number;
  reviewCount: number;
  bestRating?: number;
  worstRating?: number;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'AggregateRating',
    ratingValue: reviews.ratingValue,
    reviewCount: reviews.reviewCount,
    bestRating: reviews.bestRating ?? 5,
    worstRating: reviews.worstRating ?? 1,
  };
}

/**
 * AI-Optimized metadata helper
 * Adds markers for AI crawlers and summarization engines
 */
export function getAiMetadata(
  content: string,
  locale: 'en' | 'ar' = 'en'
) {
  return {
    // Machine-readable content summary for AI indexing
    aiSummary: content.slice(0, 500), // First 500 chars as AI summary
    // Keywords for AI understanding
    aiKeywords: locale === 'ar'
      ? ['ط¯ظˆط±ط§طھ ط¥ظ†ط¬ظ„ظٹط²ظٹ', 'طھط¹ظ„ظٹظ… ط§ظ„ظ„ط؛ط©', 'ظ…ط¹ظ‡ط¯ ظ…ط¹طھظ…ط¯', 'ط§ط®طھط¨ط§ط± طھط­ط¯ظٹط¯ ظ…ط³طھظˆظ‰']
      : ['English courses', 'language learning', 'accredited institute', 'placement test'],
    // Content type hint for AI parsing
    contentType: 'EducationalContent',
    // AI accessibility marker
    aiAccessible: true,
  };
}

